// Production model: stations st1..st4, colour counts, OF, andon
const prod = global.get('prod') || { stations: {}, color: {}, order: {}, andon: [] };
const t = msg.topic.split('/');            // cplab/prod/<x>/<y>
const now = Date.now();
if (t[2] === 'color' && t[3] === 'count') prod.color = msg.payload;
else if (t[2] === 'color' && t[3] === 'last') prod.lastColor = Object.assign({ ts: now }, msg.payload);
else if (t[2] === 'order') prod.order = msg.payload || {};
else if (t[2] === 'andon') {
  prod.andon.unshift(Object.assign({ ts: now }, msg.payload));
  prod.andon = prod.andon.slice(0, 20);
  node.warn(`ANDON ${msg.payload.type} from ${msg.payload.from}`);
}
else if (/^st[1-4]$/.test(t[2]) && t[3] === 'count') prod.stations[t[2]] = Object.assign({}, msg.payload, { seen: now });
global.set('prod', prod);

const keys = ['st1', 'st2', 'st3', 'st4'];
const wipMax = (prod.order && prod.order.wip_max) || 3;
const buffers = [];
for (let i = 0; i < 3; i++) {
  const a = prod.stations[keys[i]], b = prod.stations[keys[i + 1]];
  const wip = (a && b) ? a.count - b.count : null;
  const level = wip === null ? 'unknown' : wip < 0 ? 'error' : wip > wipMax ? 'over' : wip === wipMax ? 'limit' : 'ok';
  buffers.push({ from: keys[i], to: keys[i + 1], wip, level });
}
const colors = ['RED', 'GREEN', 'BLUE', 'BLACK'].map(c => ({
  c, n: (prod.color && prod.color[c]) || 0, target: (prod.order && prod.order.qty && prod.order.qty[c]) || 0
}));
let bottleneck = null;
keys.forEach(k => { const s = prod.stations[k]; if (s && s.cycle_ms && (!bottleneck || s.cycle_ms > bottleneck.cycle_ms)) bottleneck = { id: k, cycle_ms: s.cycle_ms }; });
return { payload: {
  stations: keys.map(k => prod.stations[k] || { id: k }),
  buffers, colors, unknown: (prod.color && prod.color.UNKNOWN) || 0,
  order: prod.order, wipMax, bottleneck, andon: prod.andon.slice(0, 8), lastColor: prod.lastColor || null
}};

// Converts dashboard requests into MQTT messages (same protocol as the web site)
const p = msg.payload || {};
const out = { qos: 1 };
switch (msg.topic) {
  case 'cmd':      // {target, kind:'msg'|'action', ...}
    out.topic = `cplab/cmd/${p.target || 'all'}/${p.kind === 'action' ? 'action' : 'msg'}`;
    out.payload = p.kind === 'action'
      ? Object.assign({}, p.data || {}, { cmd: p.cmd })
      : { text: p.text || '', from: p.from || 'Node-RED', level: p.level || 'info', duration: Number(p.duration) || 15 };
    out.retain = false; break;
  case 'order':    // OF -> retained so every Tab5 gets it at (re)connection
    out.topic = 'cplab/prod/order'; out.payload = p; out.retain = true; break;
  case 'plan':     // {id:'m1', plan:{prev:{date,task}, cur:{date,task}}}
    out.topic = `cplab/maint/${p.id}/plan/set`; out.payload = p.plan; out.retain = false; break;
  case 'ack':
    out.topic = `cplab/maint/${p.id}/ack`; out.payload = { id: p.id, by: 'superviseur' }; out.retain = false; break;
  default: return null;
}
node.status({ fill: 'blue', shape: 'dot', text: out.topic });
return out;

// Maintenance model: machine states, breakdown history, plans -> stats
const M = global.get('maint') || { machines: {}, history: {}, plans: {}, events: [] };
const now = Date.now(), DAY = 864e5;
const IDS = ['m1', 'm2', 'm3', 'm4'];
const changed = new Set();
const t = (msg.topic || '').split('/');                  // cplab/maint/m1/state

function stats(id) {
  const h = (M.history[id] || []);
  const day = h.filter(e => now - e.start < DAY).length;
  const week = h.filter(e => now - e.start < 7 * DAY).length;
  const closed = h.filter(e => e.end && now - e.start < 7 * DAY);
  const mttr = closed.length ? closed.reduce((s, e) => s + (e.end - e.start), 0) / closed.length / 60000 : null;
  const p = M.plans[id] || {};
  return { id, day, week,
    mttr_min: mttr === null ? null : Math.round(mttr * 10) / 10,
    mtbf_h: week ? Math.round(168 / week * 10) / 10 : null,
    next_prev: p.prev || null, next_cur: p.cur || null, ts: now };
}

if (msg.topic === 'tick') IDS.forEach(id => changed.add(id));
else if (t[3] === 'state') {
  const id = t[2], st = msg.payload.state, prev = M.machines[id];
  if (!prev || prev.state !== st) {
    M.events.unshift({ ts: now, id, from: prev ? prev.state : null, to: st, reason: msg.payload.reason || '', sim: !!msg.payload.sim });
    M.events = M.events.slice(0, 100);
    M.history[id] = M.history[id] || [];
    if (prev && prev.state === 'ABNORMAL') { const last = M.history[id][M.history[id].length - 1]; if (last && !last.end) last.end = now; }
    if (st === 'ABNORMAL') M.history[id].push({ start: now, reason: msg.payload.reason || '', sim: !!msg.payload.sim });
    M.history[id] = M.history[id].filter(e => now - e.start < 30 * DAY);
    changed.add(id);
  }
  M.machines[id] = Object.assign({}, msg.payload, { seen: now });
}
else if (t[3] === 'plan') { M.plans[t[2]] = Object.assign(M.plans[t[2]] || {}, msg.payload); changed.add(t[2]); }
else if (t[3] === 'ack') { M.events.unshift({ ts: now, id: t[2], to: 'ACK', reason: (msg.payload && msg.payload.by) || '' }); }
global.set('maint', M);

const statMsgs = [...changed].map(id => ({ topic: `cplab/maint/${id}/stats`, payload: stats(id), retain: true, qos: 1 }));
const dash = { payload: {
  machines: IDS.map(id => Object.assign({ id }, M.machines[id] || {}, { stats: stats(id), plan: M.plans[id] || {} })),
  events: M.events.slice(0, 30) } };
return [statMsgs, dash];

// Converts dashboard requests into MQTT messages (same protocol as the web site)
const p = msg.payload || {};
const out = { qos: 1 };
switch (msg.topic) {
  case 'cmd':      // {target, kind:'msg'|'action', ...}
    out.topic = `cplab/cmd/${p.target || 'all'}/${p.kind === 'action' ? 'action' : 'msg'}`;
    out.payload = p.kind === 'action'
      ? Object.assign({}, p.data || {}, { cmd: p.cmd })
      : { text: p.text || '', from: p.from || 'Node-RED', level: p.level || 'info', duration: Number(p.duration) || 15 };
    out.retain = false; break;
  case 'order':    // OF -> retained so every Tab5 gets it at (re)connection
    out.topic = 'cplab/prod/order'; out.payload = p; out.retain = true; break;
  case 'plan':     // {id:'m1', plan:{prev:{date,task}, cur:{date,task}}}
    out.topic = `cplab/maint/${p.id}/plan/set`; out.payload = p.plan; out.retain = false; break;
  case 'ack':
    out.topic = `cplab/maint/${p.id}/ack`; out.payload = { id: p.id, by: 'superviseur' }; out.retain = false; break;
  default: return null;
}
node.status({ fill: 'blue', shape: 'dot', text: out.topic });
return out;

// Converts dashboard requests into MQTT messages (same protocol as the web site)
const p = msg.payload || {};
const out = { qos: 1 };
switch (msg.topic) {
  case 'cmd':      // {target, kind:'msg'|'action', ...}
    out.topic = `cplab/cmd/${p.target || 'all'}/${p.kind === 'action' ? 'action' : 'msg'}`;
    out.payload = p.kind === 'action'
      ? Object.assign({}, p.data || {}, { cmd: p.cmd })
      : { text: p.text || '', from: p.from || 'Node-RED', level: p.level || 'info', duration: Number(p.duration) || 15 };
    out.retain = false; break;
  case 'order':    // OF -> retained so every Tab5 gets it at (re)connection
    out.topic = 'cplab/prod/order'; out.payload = p; out.retain = true; break;
  case 'plan':     // {id:'m1', plan:{prev:{date,task}, cur:{date,task}}}
    out.topic = `cplab/maint/${p.id}/plan/set`; out.payload = p.plan; out.retain = false; break;
  case 'ack':
    out.topic = `cplab/maint/${p.id}/ack`; out.payload = { id: p.id, by: 'superviseur' }; out.retain = false; break;
  default: return null;
}
node.status({ fill: 'blue', shape: 'dot', text: out.topic });
return out;

// Device registry from LWT + heartbeat
const D = global.get('devices') || {};
const t = msg.topic.split('/');               // cplab/status/<id> | cplab/hb/<id> | cplab/ack/<id>
const id = t[2], now = Date.now();
D[id] = D[id] || { id };
if (t[1] === 'status') D[id].online = String(msg.payload) === 'online';
else if (t[1] === 'hb') { Object.assign(D[id], msg.payload); D[id].online = true; D[id].seen = now; }
else if (t[1] === 'ack') { D[id].lastAck = { ts: now, text: msg.payload && msg.payload.text }; }
global.set('devices', D);
const list = Object.values(D).sort((a, b) => a.id.localeCompare(b.id))
  .map(d => Object.assign({}, d, { stale: d.seen ? (now - d.seen > 30000) : true }));
return { payload: list };

flow.set('sim', msg.payload === true);
node.status({ fill: msg.payload ? 'green' : 'grey', shape: 'dot', text: msg.payload ? 'simulation ON' : 'simulation OFF' });
return null;

// Coherent line simulation: pieces flow st1 -> st4, st3 is the bottleneck
if (!flow.get('sim')) return null;
const S = flow.get('simState') || { c: [0, 0, 0, 0], last: [0, 0, 0, 0], cyc: [0, 0, 0, 0], col: { RED: 0, GREEN: 0, BLUE: 0, BLACK: 0, UNKNOWN: 0 }, m: ['RUN', 'RUN', 'RUN', 'RUN'], mt: [0, 0, 0, 0], tick: 0 };
const now = Date.now(), wipMax = 3, out = [];
const p = [0.30, 0.35, 0.22, 0.45];           // chance per second to finish a piece
const names = ['Magasin', 'Presse', 'Controle', 'Controle couleur'];
S.tick++;
for (let i = 3; i >= 0; i--) {
  const upstreamOk = i === 0 ? (S.c[0] - S.c[1] <= wipMax) : (S.c[i - 1] > S.c[i]);
  if (S.m[i] === 'RUN' && upstreamOk && Math.random() < p[i]) {
    if (S.last[i]) S.cyc[i] = now - S.last[i];
    S.last[i] = now; S.c[i]++;
    if (i === 3) {
      const r = Math.random(); const col = r < .27 ? 'RED' : r < .52 ? 'GREEN' : r < .77 ? 'BLUE' : r < .98 ? 'BLACK' : 'UNKNOWN';
      S.col[col]++; out.push({ topic: 'cplab/prod/color/last', payload: { color: col, sim: true } });
    }
  }
}
for (let i = 0; i < 4; i++) {
  const wip = i < 3 ? S.c[i] - S.c[i + 1] : -1;
  const kanban = i === 3 ? 'GREEN' : wip > wipMax ? 'RED' : wip === wipMax ? 'AMBER' : 'GREEN';
  out.push({ topic: `cplab/prod/st${i + 1}/count`, retain: true, payload: { st: i + 1, id: 'st' + (i + 1), name: names[i], count: S.c[i],
    cycle_ms: S.cyc[i], cadence: S.cyc[i] ? Math.round(600000 / S.cyc[i]) / 10 : 0, takt_s: 20, wip_out: wip, wip_max: wipMax, kanban,
    state: now - S.last[i] < 15000 ? 'RUN' : 'WAIT', sim: true } });
}
out.push({ topic: 'cplab/prod/color/count', retain: true, payload: Object.assign({ total: S.c[3] }, S.col) });
// maintenance: random breakdowns (~1 every 4 min per machine), repaired after 20-60 s
for (let i = 0; i < 4; i++) {
  if (S.m[i] === 'RUN' && Math.random() < 1 / 240) { S.m[i] = 'ABNORMAL'; S.mt[i] = now + 20000 + Math.random() * 40000; }
  else if (S.m[i] === 'ABNORMAL' && now > S.mt[i]) { S.m[i] = 'RUN'; }
  if (S.tick % 5 === 0 || S.m[i] !== (S.prevM || [])[i])
    out.push({ topic: `cplab/maint/m${i + 1}/state`, retain: true, payload: { m: i + 1, id: 'm' + (i + 1), name: 'Machine ' + (i + 1),
      state: S.m[i], reason: S.m[i] === 'ABNORMAL' ? 'Vibrations excessives' : '', activity: S.m[i] === 'ABNORMAL' ? 95 : 25 + Math.random() * 8, sim: true } });
}
S.prevM = S.m.slice();
flow.set('simState', S);
node.status({ fill: 'green', shape: 'ring', text: 'out: ' + S.c[3] });
return [out];

// Creates the OPC UA variables when the flow starts (spec section 7):
// one String variable per MQTT topic, NodeId ns=1;s=<full topic>, value = JSON payload.
// Devices write there while the broker is down (state OPC_FALLBACK).
const root = env.get("CPLAB_ROOT") || "cplab";
const DEVICES = {
    "prod-st1": ["prod/st1/count"],
    "prod-st2": ["prod/st2/count"],
    "prod-st3": ["prod/st3/count"],
    "prod-color": ["prod/color/last", "prod/color/count", "prod/st4/count"],
    "prod-hmi": ["prod/andon"],
    "maint-m1": ["maint/m1/state", "maint/m1/ack"],
    "maint-m2": ["maint/m2/state", "maint/m2/ack"],
    "maint-m3": ["maint/m3/state", "maint/m3/ack"],
    "maint-m4": ["maint/m4/state", "maint/m4/ack"],
};
const out = [];
for (const [dev, topics] of Object.entries(DEVICES)) {
    for (const t of [...topics, `rel/${dev}/status`]) {
        out.push({ topic: `ns=1;s=${root}/${t};datatype=String`, payload: { opcuaCommand: "addVariable" } });
    }
}
node.status({ fill: "green", shape: "dot", text: out.length + " variables" });
return [out];

// The OPC UA server sends a message each time a client (Tab5) writes a variable:
// payload = {messageType:"Variable", variableName:"1:cplab/prod/st1/count", variableValue:"{json}"}.
// Turn it back into an MQTT-like message tagged path "OPCUA".
const p = msg.payload;
if (!p || p.messageType !== "Variable" || typeof p.variableValue !== "string") return null;
let data;
try { data = JSON.parse(p.variableValue); } catch (e) { return null; }
const topic = String(p.variableName).replace(/^\d+:/, "");
node.status({ fill: "blue", shape: "dot", text: topic.split("/").slice(1).join("/") + " " + new Date().toLocaleTimeString() });
return { topic: topic, payload: data, path: "OPCUA", retain: false };

// Merges MQTT and OPC UA into one stream, tags the path, drops replayed copies
// by seq and counts sent vs received per device (spec v5 sections 6, 8, 10).
// in : MQTT messages (cplab/#), OPC UA writes (msg.path = "OPCUA"),
//      msg.topic "tick" every second, "reset" to clear the counters.
// out 1: one message per new value {topic, payload, path: MQTT|REPLAY|OPCUA, device, retain}
// out 2: reliability summary per device, for the WebSocket relay
// out 3: table of all devices, for the dashboard
const ROOT = (env.get("CPLAB_ROOT") || "cplab") + "/";
const STALE_MS = 5000;
const SOURCE = { MQTT: "MQTT direct", BUFFER: "Tampon local (Tab5)", OPCUA: "OPC UA (Node-RED)", REPLAY: "Rejeu MQTT" };
const now = Date.now();
let devs = flow.get("rel") || {};

function devOf(sub) {                       // device that publishes a data topic
    const p = sub.split("/");
    if (p[0] === "prod" && /^st[1-3]$/.test(p[1])) return "prod-" + p[1];
    if (p[0] === "prod" && (p[1] === "st4" || p[1] === "color")) return "prod-color";
    if (p[0] === "prod" && p[1] === "andon" && p.length === 2) return "prod-hmi";
    if (p[0] === "maint" && p.length >= 3 && (p[2] === "state" || p[2] === "ack")) return "maint-" + p[1];
    return null;
}
function fresh(dev) {
    return { device: dev, boot: null, base: null, low: null, above: [], received: 0, dup: 0,
             replayed: 0, viaOpc: 0, viaMqtt: 0, sent: 0, state: "UNKNOWN", path: "?",
             buffer: null, capacity: null, dropped: 0, loopMaxMs: null, lastStatus: 0,
             statusVia: "", transitions: [] };
}
function get(dev) { return devs[dev] || (devs[dev] = fresh(dev)); }
// low = every seq up to low has arrived; above = seq received beyond low (sorted)
function record(st, seq) {
    if (st.low === null) { st.low = seq - 1; st.base = seq - 1; }
    if (seq <= st.low || st.above.includes(seq)) { st.dup++; return false; }
    st.above.push(seq);
    st.above.sort((a, b) => a - b);
    while (st.above.length && st.above[0] === st.low + 1) { st.low++; st.above.shift(); }
    st.received++;
    return true;
}
function top(st) {
    return Math.max(st.sent, st.low || 0, st.above.length ? st.above[st.above.length - 1] : 0);
}
function missingList(st, max) {
    const out = [];
    for (let s = st.low + 1, i = 0; s <= top(st) && out.length < max; s++) {
        while (i < st.above.length && st.above[i] < s) i++;
        if (st.above[i] !== s) out.push(s);
    }
    return out;
}
function summary(st) {
    const stale = !st.lastStatus || now - st.lastStatus > STALE_MS;
    const counted = st.low !== null;
    const sent = counted ? top(st) - st.base : 0;
    return { type: "reliability", device: st.device, state: st.state, stale: stale, path: st.path,
             source: SOURCE[st.path] || st.path, sent: sent, received: st.received,
             missing: counted ? sent - st.received : 0, missingSeq: counted ? missingList(st, 10) : [],
             dup: st.dup, replayed: st.replayed, viaOpc: st.viaOpc, viaMqtt: st.viaMqtt,
             dropped: st.dropped, buffer: st.buffer, capacity: st.capacity, loopMaxMs: st.loopMaxMs,
             statusVia: st.statusVia, ts: now };
}

if (msg.topic === "reset") {
    flow.set("rel", {});
    flow.set("relTable", []);
    node.status({ text: "reset " + new Date().toLocaleTimeString() });
    return [null, null, { topic: "table", payload: [] }];
}
if (msg.topic === "tick") {
    const rows = Object.values(devs).sort((a, b) => a.device.localeCompare(b.device)).map(summary);
    flow.set("relTable", rows);
    const bad = rows.filter(r => r.missing > 0).length;
    node.status({ fill: bad ? "red" : "green", shape: "dot", text: rows.length + " Tab5, " + bad + " with missing seq" });
    return [null, rows.map(r => ({ payload: r })), { topic: "table", payload: rows }];
}
if (typeof msg.topic !== "string" || !msg.topic.startsWith(ROOT)) return null;
let p = msg.payload;
if (typeof p === "string") { try { p = JSON.parse(p); } catch (e) { /* not JSON */ } }
const sub = msg.topic.slice(ROOT.length);
const via = msg.path === "OPCUA" ? "OPCUA" : "MQTT";

// ---- status topic of a Tab5: cplab/rel/<devId>/status
const m = sub.match(/^rel\/([^/]+)\/status$/);
if (m) {
    if (!p || typeof p !== "object") return null;
    let st = get(m[1]);
    if (p.boot && st.boot && p.boot !== st.boot) st = devs[m[1]] = fresh(m[1]);  // Tab5 restarted
    st.boot = p.boot || st.boot;
    // A frozen broker delivers old status messages late, all at once when it resumes:
    // keep only the newest one (ts = device time when it was published)
    if (typeof p.ts === "number") {
        if (st.lastTs && p.ts < st.lastTs) return null;
        st.lastTs = p.ts;
    }
    st.sent = Math.max(st.sent, p.seq || 0);
    st.dropped = p.dropped || 0;
    st.buffer = p.buffer;
    st.capacity = p.capacity;
    st.loopMaxMs = p.loop_max_ms;
    if (p.state !== st.state) {
        st.transitions.push({ t: now, state: p.state, via: via });
        if (st.transitions.length > 50) st.transitions.shift();
    }
    st.state = p.state;
    st.path = p.path;
    st.statusVia = via;
    if (!msg.retain) st.lastStatus = now;      // retained = old value from the broker store
    flow.set("rel", devs);
    return [null, { payload: summary(st) }, null];
}

// ---- data topic
const dev = devOf(sub);
const out = { topic: msg.topic, payload: p, path: via, device: dev, retain: !!msg.retain };
if (!dev || !p || typeof p !== "object" || typeof p.seq !== "number") return [out, null, null]; // no seq: pass through
if (p.replayed) out.path = "REPLAY";
if (msg.retain) return [out, null, null];       // value from the broker store at subscribe: not counted
let st = get(dev);
if (st.low !== null && p.seq < st.low - 1000) st = devs[dev] = fresh(dev);   // seq restarted (reboot)
// Mosquitto sends one copy per matching subscription: cplab/# here and e.g.
// cplab/prod/+/count in the Production tab share Node-RED's connection.
// Ignore those exact repeats; a replayed copy (replayed:true or via OPC UA) is still counted as dup.
const key = msg.topic + "|" + p.seq + "|" + (p.replayed ? 1 : 0) + "|" + via;
st.recent = st.recent || [];
if (st.recent.includes(key)) return null;
st.recent.push(key);
if (st.recent.length > 100) st.recent.shift();
if (!record(st, p.seq)) { flow.set("rel", devs); return null; }             // copy already received: drop it
if (via === "OPCUA") st.viaOpc++;
else if (p.replayed) st.replayed++;
else st.viaMqtt++;
flow.set("rel", devs);
return [out, null, null];

// Formats what the website receives on ws://<laptop>:1880/ws/cplab
//   {type:"reliability", device, state, source, sent, received, missing, dup, dropped, replayed, buffer, capacity, ...}
//   {type:"data", device, topic, path, payload}      every new value (MQTT, replay or OPC UA)
//   {type:"broker", connected, text}                 Node-RED's own link to Mosquitto
// This relay does not depend on Mosquitto: it keeps working when the broker is down.
let out;
if (msg.status) {
    out = { type: "broker", connected: msg.status.fill === "green", text: msg.status.text || "", ts: Date.now() };
} else if (msg.payload && msg.payload.type === "reliability") {
    out = msg.payload;
} else {
    out = { type: "data", device: msg.device, topic: msg.topic, path: msg.path, payload: msg.payload, ts: Date.now() };
}
return { payload: JSON.stringify(out) };

// Starts an outage test: saves the counters, then runs scripts/outage.sh.
// in: payload {label, seconds, mode: "stop"|"freeze"|"drop", settle}
// out 1: command for the exec node     out 2: view for the dashboard
const t = flow.get("test");
if (t && t.running) { node.warn("A test is already running: " + t.label); return null; }
const repo = env.get("CPLAB_REPO");
if (!repo) {
    node.error("Set CPLAB_REPO to the path of the cplab-tracking folder (tab properties > Environment variables, or in the shell that starts Node-RED)");
    return null;
}
const c = msg.payload || {};
const seconds = Number(c.seconds);
const mode = ["stop", "freeze", "drop"].includes(c.mode) ? c.mode : "stop";
if (!(seconds > 0 && seconds <= 300)) { node.error("seconds must be 1..300"); return null; }
const snap = {};
for (const r of (flow.get("relTable") || [])) snap[r.device] = r;
const test = { running: true, label: c.label || (seconds + " s " + mode), seconds: seconds, mode: mode,
               settle: Number(c.settle) || 20, requestedAt: Date.now(), snap: snap, stdout: "" };
flow.set("test", test);
node.status({ fill: "yellow", shape: "ring", text: test.label + ": outage running" });
const view = { running: true, phase: "outage", label: test.label, results: flow.get("testResults") || [] };
return [{ payload: `"${repo}/scripts/outage.sh" ${seconds} ${mode}` }, { payload: view }];

// outage.sh has finished: read its CSV line, then wait `settle` seconds for the
// Tab5s to recover and replay before the evaluation.
const t = flow.get("test");
if (!t || !t.running || t.done) return null;
if (typeof msg.payload === "string") {
    t.stdout += msg.payload;
    flow.set("test", t);
    if (msg.rc === undefined) return null;      // wait for the return code message
}
const code = msg.payload && msg.payload.code !== undefined ? msg.payload.code : (msg.rc ? msg.rc.code : 0);
const line = t.stdout.trim().split("\n").pop() || "";
const f = line.split(",");
t.done = true;
t.outage = { line: line, code: code, start: Date.parse(f[0]) || t.requestedAt,
             end: f[1] ? Date.parse(f[1]) : null, actual: parseFloat(f[3]) || null, result: f[5] || "no_output" };
flow.set("test", t);
node.status({ fill: "yellow", shape: "dot", text: t.label + ": waiting " + t.settle + " s for recovery" });
return [{ delay: t.settle * 1000, payload: "evaluate" },
        { payload: { running: true, phase: "recovery", label: t.label, outage: t.outage, results: flow.get("testResults") || [] } }];

// Evaluates the test against spec section 9 and appends one row per Tab5 to
// tests/test_matrix.csv. Pass = no seq missing, nothing dropped by the buffer,
// OPC UA switch only for outages >= 15 s (at 15 +/- 2 s), back on MQTT within 10 s.
const t = flow.get("test");
if (!t || !t.outage) return null;
const devs = flow.get("rel") || {};
const rows = (flow.get("relTable") || []).filter(r => !r.stale || t.snap[r.device]);
const o = t.outage;
const expectOpc = t.seconds >= 15;
const time = new Date().toISOString();
const results = [];
for (const r of rows) {
    const b = t.snap[r.device] || { sent: 0, received: 0, dup: 0, dropped: 0, replayed: 0, viaOpc: 0 };
    const tr = (devs[r.device] && devs[r.device].transitions) || [];
    const fb = tr.find(x => x.state === "OPC_FALLBACK" && x.t >= o.start);
    const back = o.end ? tr.find(x => x.state === "CONNECTED" && x.t >= o.end) : null;
    const switchS = fb ? (fb.t - o.start) / 1000 : null;
    const backS = back ? (back.t - o.end) / 1000 : null;
    const dropped = r.dropped - (b.dropped || 0);
    const notes = [];
    if (o.result !== "ok") notes.push("outage.sh: " + o.result);
    if (r.missing > 0) notes.push(r.missing + " seq missing (" + r.missingSeq.join(" ") + ")");
    if (dropped > 0) notes.push(dropped + " dropped (buffer full)");
    if (expectOpc && switchS === null) notes.push("no OPC UA switch");
    if (expectOpc && switchS !== null && Math.abs(switchS - 15) > 2) notes.push("OPC UA switch at " + switchS.toFixed(1) + " s");
    if (!expectOpc && switchS !== null) notes.push("unexpected OPC UA switch");
    if (backS === null) notes.push("not back on MQTT");
    else if (backS > 10) notes.push("back on MQTT after " + backS.toFixed(1) + " s");
    results.push({ time: time, label: t.label, mode: t.mode, requested: t.seconds, actual: o.actual,
                   device: r.device, sent: r.sent - (b.sent || 0), received: r.received - (b.received || 0),
                   missing: r.missing, dup: r.dup - (b.dup || 0), dropped: dropped,
                   replayed: r.replayed - (b.replayed || 0), viaOpc: r.viaOpc - (b.viaOpc || 0),
                   switchS: switchS, backS: backS, verdict: notes.length ? "FAIL" : "PASS", notes: notes.join("; ") });
}
const repo = env.get("CPLAB_REPO");
const file = repo + "/tests/test_matrix.csv";
const cols = ["time", "label", "mode", "requested", "actual", "device", "sent", "received", "missing", "dup",
              "dropped", "replayed", "viaOpc", "switchS", "backS", "verdict", "notes"];
const esc = v => v === null || v === undefined ? "" : (/[",]/.test(String(v)) ? '"' + String(v).replace(/"/g, '""') + '"' : String(v));
try {
    if (!fs.existsSync(file)) fs.writeFileSync(file, "time_utc,label,mode,requested_s,actual_s,device,sent,received,missing,dup_dropped,buffer_dropped,replayed,via_opc,switch_to_opc_s,back_on_mqtt_s,verdict,notes\n");
    fs.appendFileSync(file, results.map(r => cols.map(c => esc(typeof r[c] === "number" ? Math.round(r[c] * 10) / 10 : r[c])).join(",")).join("\n") + "\n");
} catch (e) { node.error("Cannot write " + file + ": " + e.message); }
const all = (flow.get("testResults") || []).concat(results).slice(-60);
flow.set("testResults", all);
t.running = false;
flow.set("test", t);
const fails = results.filter(r => r.verdict === "FAIL").length;
node.status({ fill: fails ? "red" : "green", shape: "dot", text: t.label + ": " + (fails ? fails + " FAIL" : "PASS") });
return { payload: { running: false, phase: "done", label: t.label, outage: o, results: all } };
